#!/usr/bin/env python3
"""JSON normalizer: reads one JSON value from STDIN, writes canonical compact text.

Supported: null/true/false, decimal integers (optional '-', no leading zeros,
'-0' -> 0), strings, arrays, objects (string keys). String escapes limited to
\" \\ \/ \n \t \uXXXX ; decoded code point must be >= 0x20.
Duplicate object keys: last wins. Object keys sorted by code point.
Any syntax error / trailing content / bad escape / bad number / empty input:
print a single line 'ERR'.

Selftest: python3 this_file.py --selftest   (prints PASS/FAIL, exit 0/1)
Run:      echo -n '{"a":1,"b":[2,3]}' | python3 this_file.py
"""
import sys

WS = " \t\n\r"


class Err(Exception):
    pass


class P:
    __slots__ = ("s", "i", "n")

    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def ws(self):
        while self.i < self.n and self.s[self.i] in WS:
            self.i += 1

    def peek(self):
        return self.s[self.i] if self.i < self.n else ""

    def eat(self, c):
        if self.peek() != c:
            raise Err()
        self.i += 1

    def value(self):
        self.ws()
        c = self.peek()
        if c == "":
            raise Err()
        if c == "n":
            return self.lit("null", None)
        if c == "t":
            return self.lit("true", True)
        if c == "f":
            return self.lit("false", False)
        if c == '"':
            return ("str", self.string())
        if c == "[":
            return ("arr", self.array())
        if c == "{":
            return ("obj", self.obj())
        if c == "-" or c.isdigit():
            return ("num", self.number())
        raise Err()

    def lit(self, word, val):
        if self.s[self.i:self.i + len(word)] != word:
            raise Err()
        self.i += len(word)
        return val

    def string(self):
        self.eat('"')
        out = []
        while True:
            if self.i >= self.n:
                raise Err()
            c = self.s[self.i]
            if c == '"':
                self.i += 1
                return "".join(out)
            if c == "\\":
                self.i += 1
                if self.i >= self.n:
                    raise Err()
                e = self.s[self.i]
                self.i += 1
                if e == '"':
                    out.append('"')
                elif e == "\\":
                    out.append("\\")
                elif e == "/":
                    out.append("/")
                elif e == "n":
                    out.append("\n")
                elif e == "t":
                    out.append("\t")
                elif e == "u":
                    h = self.s[self.i:self.i + 4]
                    if len(h) != 4 or any(ch not in "0123456789abcdefABCDEF" for ch in h):
                        raise Err()
                    self.i += 4
                    cp = int(h, 16)
                    if cp < 0x20:
                        raise Err()
                    out.append(chr(cp))
                else:
                    raise Err()
            elif ord(c) < 0x20:
                raise Err()
            else:
                out.append(c)
                self.i += 1

    def number(self):
        start = self.i
        if self.peek() == "-":
            self.i += 1
        if self.i >= self.n or not self.s[self.i].isdigit():
            raise Err()
        if self.s[self.i] == "0":
            self.i += 1
            if self.i < self.n and self.s[self.i].isdigit():
                raise Err()
        else:
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
        raw = self.s[start:self.i]
        v = int(raw)
        return 0 if v == 0 else v

    def array(self):
        self.eat("[")
        self.ws()
        items = []
        if self.peek() == "]":
            self.i += 1
            return items
        while True:
            items.append(self.value())
            self.ws()
            c = self.peek()
            if c == ",":
                self.i += 1
                self.ws()
                continue
            if c == "]":
                self.i += 1
                return items
            raise Err()

    def obj(self):
        self.eat("{")
        self.ws()
        d = {}
        if self.peek() == "}":
            self.i += 1
            return d
        while True:
            self.ws()
            if self.peek() != '"':
                raise Err()
            k = self.string()
            self.ws()
            self.eat(":")
            d[k] = self.value()
            self.ws()
            c = self.peek()
            if c == ",":
                self.i += 1
                continue
            if c == "}":
                self.i += 1
                return d
            raise Err()


def esc(s):
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        else:
            out.append(ch)
    out.append('"')
    return "".join(out)


def dump(v):
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    tag = type(v)
    if tag is tuple:
        kind, val = v
        if kind == "num":
            return str(val)
        if kind == "str":
            return esc(val)
        if kind == "arr":
            return "[" + ",".join(dump(x) for x in val) + "]"
        return "{" + ",".join(esc(k) + ":" + dump(val[k]) for k in sorted(val)) + "}"
    raise Err()


def normalize(text):
    p = P(text)
    v = p.value()
    p.ws()
    if p.i != p.n:
        raise Err()
    return dump(v)


def selftest():
    cases = [
        ("-33", "-33"),
        ('["\\\\9\\u4e2d/",  null\n]', '["\\\\9\u4e2d/",null]'),
        ('{"a":1,"b":[2,3]}', '{"a":1,"b":[2,3]}'),
        ("  null  ", "null"),
        ("true", "true"),
        ("false", "false"),
        ("0", "0"),
        ("-0", "0"),
        ("[]", "[]"),
        ("{}", "{}"),
        ('"a\\nb\\tc"', '"a\\nb\\tc"'),
        ('{"b":2,"a":1,"b":3}', '{"a":1,"b":3}'),
        ("[1,2,3]", "[1,2,3]"),
        ('{"k":"v"}', '{"k":"v"}'),
        ("", None),
        ("  ", None),
        ("nul", None),
        ("01", None),
        ("-", None),
        ("[1,]", None),
        ("{1:2}", None),
        ('"\\x"', None),
        ('"\\u00zz"', None),
        ('"\\u001f"', None),
        ("1 2", None),
        ("[1 2]", None),
        ("{", None),
        ('"unterminated', None),
        ("[", None),
        ("tru", None),
    ]
    ok = True
    for src, want in cases:
        try:
            got = normalize(src)
        except Err:
            got = None
        except Exception:
            got = None
        if want is None:
            good = got is None
        else:
            good = got == want
        if not good:
            ok = False
        print("PASS" if good else "FAIL")
    print("PASS" if ok else "FAIL")
    return 0 if ok else 1


def main(argv):
    if len(argv) > 1 and argv[1] == "--selftest":
        return selftest()
    text = sys.stdin.read()
    try:
        sys.stdout.write(normalize(text) + "\n")
    except Err:
        sys.stdout.write("ERR\n")
    except Exception:
        sys.stdout.write("ERR\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
